import React, { useState } from "react";
import { Box, Typography, Button, Grid, Paper } from "@mui/material";

const candidates = {
  "Position 1": [
    { id: 1, name: "Candidate 1a" },
    { id: 2, name: "Candidate 1b" },
    { id: 3, name: "Candidate 1c" },
  ],
  "Position 2": [
    { id: 4, name: "Candidate 2a" },
    { id: 5, name: "Candidate 2b" },
    { id: 6, name: "Candidate 2c" },
    { id: 7, name: "Candidate 2d" },
  ],
  "Position 3": [
    { id: 8, name: "Candidate 3a" },
    { id: 9, name: "Candidate 3b" },
    { id: 10, name: "Candidate 3c" },
    { id: 11, name: "Candidate 3d" },
    { id: 12, name: "Candidate 3e" },
  ],
  "Position 4": [
    { id: 13, name: "Candidate 4a" },
    { id: 14, name: "Candidate 4b" },
    { id: 15, name: "Candidate 4c" },
  ],
};

const VotingPage = () => {
  const [selectedCandidates, setSelectedCandidates] = useState({});

  const handleVote = (position, candidateId) => {
    setSelectedCandidates((prev) => ({
      ...prev,
      [position]: candidateId,
    }));
  };

  return (
    <Box sx={{ p: 3, textAlign: "center" }}>
      <Typography variant="h4" fontWeight="bold" gutterBottom>
        Cast Your Votes
      </Typography>
      {Object.entries(candidates).map(([position, candidatesList]) => (
        <Box key={position} sx={{ mb: 4 }}>
          <Typography variant="h5" fontWeight="bold" gutterBottom>
            {position}
          </Typography>
          <Grid container spacing={3} justifyContent="center">
            {candidatesList.map((candidate) => (
              <Grid item key={candidate.id}>
                <Paper
                  elevation={3}
                  sx={{
                    width: 180,
                    height: 250,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    justifyContent: "space-between",
                    p: 2,
                    borderRadius: 3,
                  }}
                >
                  <Box
                    sx={{
                      width: 100,
                      height: 100,
                      backgroundColor: "#ddd",
                      borderRadius: 2,
                      mb: 2,
                    }}
                  />
                  <Typography>{candidate.name}</Typography>
                  <Button
                    variant={
                      selectedCandidates[position] === candidate.id
                        ? "contained"
                        : "outlined"
                    }
                    color="primary"
                    onClick={() => handleVote(position, candidate.id)}
                    fullWidth
                  >
                    CAST VOTE
                  </Button>
                  <Button variant="outlined" color="secondary" fullWidth>
                    MANIFESTO
                  </Button>
                </Paper>
              </Grid>
            ))}
          </Grid>
        </Box>
      ))}
      <Button
        variant="contained"
        sx={{ backgroundColor: "#28a745", color: "white", mt: 4, px: 4, py: 2 }}
      >
        CONFIRM VOTES
      </Button>
    </Box>
  );
};

export default VotingPage;
